-- 00015_guides.sql
-- Practical guides: mental game, recovery, nutrition, injury prevention,
-- jumping higher and game-day prep. Read-only for players. Safe to re-run.

CREATE TABLE IF NOT EXISTS public.guides (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text UNIQUE NOT NULL,
  category text NOT NULL CHECK (category IN ('mental_game', 'recovery', 'nutrition', 'injury_prevention', 'vertical', 'game_prep')),
  title text NOT NULL,
  summary text NOT NULL,
  reading_minutes smallint NOT NULL DEFAULT 5,
  sections jsonb NOT NULL DEFAULT '[]',
  display_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.guides ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Players can view guides" ON public.guides;
CREATE POLICY "Players can view guides" ON public.guides FOR SELECT TO authenticated USING (true);

GRANT SELECT ON public.guides TO authenticated;
GRANT ALL ON public.guides TO service_role;
REVOKE ALL ON public.guides FROM anon;

-- =============================================================================
-- GUIDES
-- =============================================================================
-- HoopIQ practical guides (safe to re-run)
INSERT INTO public.guides (slug, category, title, summary, reading_minutes, sections, display_order) VALUES
('building-shooter-confidence', 'mental_game', 'Building Confidence as a Shooter', 'Real shooting confidence comes from evidence you build in practice. Learn make-based workouts, process goals, and self-talk that holds up in games.', 5, '[{"heading":"Where confidence really comes from","body":"Confidence is not a mood you wait for. It is your brain''s best guess about what will happen, based on what you have seen yourself do. The more quality reps you stack up, the more evidence your brain has that the ball is going in.\n\nThat means confidence is something you can build on purpose:\n- Put in reps that look like game shots\n- Track your progress so you can see it\n- Talk to yourself like a good teammate would\n- Judge yourself on your process, not on one miss"},{"heading":"Start close and earn your range","body":"Many players try to build confidence from deep and end up practicing misses. Start where you make a lot and move out as you earn it.\n\nA simple make-based ladder:\n- Form shooting 1 to 2 steps from the rim: make 10 with one hand, then 10 with your normal form\n- Short mid-range spots (5 spots around the key): make 5 in a row at each spot before moving\n- Elbows and free-throw line: make 7 out of 10 before moving back\n- Three-point range: only once your mid-range form stays the same\n\nIf your form breaks down when you move back, you are too far out for now. Step in, rebuild the rhythm, and try again next session."},{"heading":"Practice shots you will actually take","body":"Game shots come off the catch, off the dribble, and when you are a bit tired. Mix in:\n- Catch-and-shoot with a partner pass or a self-toss, feet ready before the ball arrives\n- One-dribble pull-ups going left and right\n- Shots at game speed after a sprint, so tired legs feel normal\n- A few shots with a partner closing out with a hand up\n\nEnd each session on a make streak, like 3 swishes in a row from your favorite spot, so the last picture in your head is a good one."},{"heading":"Track the process, not just makes","body":"Your percentage will bounce around from day to day. Your process is what you control. After each session, rate yourself on things like:\n- Did I use the same routine and rhythm on every shot?\n- Were my feet set and balanced?\n- Did I hold my follow-through?\n- Did I shoot game-speed shots?\n\nLog your makes and attempts in the app too. Over weeks, the trend matters far more than any single day. Looking back at your log on a bad day is proof that you can shoot."},{"heading":"Self-talk and handling a cold streak","body":"What you say to yourself after a miss shapes the next shot. Swap judgment for instruction:\n- Instead of \"I can''t hit anything,\" try \"Legs and follow through.\"\n- Instead of \"Don''t miss,\" try \"Smooth and high.\"\n- Instead of \"I''m terrible today,\" try \"Next one''s going.\"\n\nWhen you are cold in a game:\n- Keep taking good shots, and pass up rushed or heavily contested ones\n- Get an easy one: a layup, a free throw, or a short shot to see the ball go in\n- Focus on one cue only, not a full list\n- Remember your practice log. One cold game does not erase hundreds of good reps"}]'::jsonb, 1),
('pre-shot-free-throw-routines', 'mental_game', 'Pre-Shot and Free-Throw Routines', 'Build a simple, repeatable free-throw routine and a quick pre-shot habit so your shot looks the same in a tight game as it does in practice.', 5, '[{"heading":"Why routines work","body":"A routine is a short, repeatable set of actions you do before every shot. It gives your mind a job so there is less room for worry, and it helps your body find the same rhythm every time.\n\nA good routine is:\n- Short, usually a few seconds\n- Exactly the same every time\n- Focused on one or two simple cues\n- Something you practice as much as the shot itself"},{"heading":"Build your free-throw routine","body":"Try this template, then adjust it until it feels like yours:\n- Step to the line and find your spot. Many players line up their shooting foot with the small nail hole or center of the line\n- Take a breath in through your nose and out slowly through your mouth\n- Take the same number of dribbles every time, for example 2 or 3\n- Spin the ball into your grip and find the seams the same way\n- Eyes on the target, the front of the rim or just over it\n- Say one cue word, like \"smooth\" or \"up\"\n- Shoot and hold your follow-through until the ball lands\n\nOnce you pick it, do not change it in the middle of a game. Tweaks belong in practice."},{"heading":"Practice it under pressure","body":"Free throws in games happen when you are tired and people are watching. Practice those conditions:\n- Shoot free throws between sprints or right after a tough drill\n- Shoot in pairs, like a real trip to the line, and track how many pairs you make both\n- Set a challenge, such as making 2 in a row before you can leave, or run a lap for every miss\n- Have a teammate talk or make noise while you shoot\n- Use your full routine every single time, even when you are just messing around\n\nA practice free throw without your routine does not count toward building the habit."},{"heading":"A quick pre-shot routine for live play","body":"In live play you do not have time for dribbles and breaths, but you can still be consistent:\n- Hands ready and knees bent before the catch\n- Feet moving into position as the ball comes, often a 1-2 step or a hop\n- Eyes to the rim early\n- Same rise and release every time\n\nThink of it as being \"shot-ready.\" The routine happens before the ball arrives, so the shot itself stays automatic."},{"heading":"Common mistakes","body":"- Changing the routine after a miss. Stick with it\n- A routine that takes too long and makes you overthink\n- Too many cues at once. Pick one\n- Only using the routine in games. It needs hundreds of practice reps to feel natural\n- Rushing when nervous. Your breath is the brake, so use it every time"}]'::jsonb, 2),
('bouncing-back-from-mistakes', 'mental_game', 'Bouncing Back from Mistakes', 'Turnovers, missed shots, and bad calls happen to everyone. Learn a next-play reset, better self-talk, and how to review games without replaying them.', 5, '[{"heading":"Mistakes are part of the game","body":"Every player makes mistakes, including the best players you have ever watched. Basketball moves fast, and you will miss shots, throw bad passes, and get beaten on defense. What separates good players is how fast they get back to the next play.\n\nA mistake costs you one possession. Dwelling on it can cost you the next five."},{"heading":"The next-play reset","body":"Build a quick physical cue that tells your brain the play is over. Pick one and use it every time:\n- Clap your hands once\n- Wipe your hand on your shorts or jersey\n- Touch the floor\n- Take one deep breath out as you run back\n\nPair it with a short phrase like \"next play\" or \"flush it.\" Then give yourself a job right away: sprint back, find your player, talk on defense. Having a job pulls your focus forward."},{"heading":"Change the story you tell yourself","body":"After a mistake, your inner voice can go negative fast. Notice it and replace it:\n- \"I always mess up\" becomes \"That one''s done. Next play.\"\n- \"Coach is going to pull me\" becomes \"What can I control right now? Effort and defense.\"\n- \"Everyone saw that\" becomes \"Everyone makes mistakes. Keep playing hard.\"\n\nTalk to yourself the way you would talk to a teammate who just turned it over. You would not yell at them. You would pick them up."},{"heading":"Learn from it after the game, not during it","body":"During the game, your only job is the next play. After the game, you can learn:\n- Write down 2 or 3 things that went well and 1 or 2 things to work on\n- Ask what caused the mistake. Was it decision, technique, or fatigue?\n- Turn it into a practice goal, like \"work on left-hand passes out of a drive\"\n- If you have video, watch it once to learn, not over and over to punish yourself\n\nThen let it go. Replaying a mistake in your head all night does not make you better. Practicing the fix does."},{"heading":"When it feels heavier than a bad game","body":"Sometimes the pressure builds up. If you notice any of these for more than a couple of weeks, talk to someone you trust, like a parent, coach, school counselor, or doctor:\n- You dread practice or games that you used to enjoy\n- You cannot stop thinking about mistakes, even days later\n- It is affecting your sleep, eating, school, or mood\n- You feel like you are only worth something when you play well\n\nAsking for help is a strength. Your worth is much bigger than any stat line."}]'::jsonb, 3),
('visualization-for-hoopers', 'mental_game', 'Visualization for Hoopers', 'Use mental rehearsal to sharpen your shot, moves, and game decisions. Includes a simple 5-minute routine you can do before bed or before games.', 5, '[{"heading":"What visualization is","body":"Visualization, also called mental rehearsal or imagery, means picturing yourself performing a skill in detail. Athletes in many sports use it to prepare for competition, stay calm, and reinforce good technique.\n\nIt does not replace real practice. Think of it as extra reps you can do anywhere: on the bus, in bed, or in the locker room."},{"heading":"Make it vivid","body":"The more real it feels, the more useful it is. Use all your senses:\n- See it from your own eyes, as if you are in your body on the court\n- Hear the ball bouncing, sneakers squeaking, teammates calling out\n- Feel the grip of the ball, your legs loading, the release off your fingertips\n- Play it at real speed, not slow motion, once you know the skill well\n\nAlways picture a successful result: the ball going in, the clean pass, the stop on defense."},{"heading":"A 5-minute routine","body":"Find a quiet place, sit or lie down, and close your eyes.\n- Minute 1: Slow breathing. Breathe in for about 4 counts and out for about 6 counts\n- Minute 2: Picture the gym or court where you will play. Notice the lights, the rim, the floor\n- Minute 3: Picture 5 free throws using your full routine. See each one go in\n- Minute 4: Picture 3 game plays, like a catch-and-shoot three, a drive and kick, and a defensive stop\n- Minute 5: Picture yourself staying calm after a mistake and making the next play\n\nOpen your eyes, take one more deep breath, and you are done."},{"heading":"When to use it","body":"- The night before a game, as part of winding down\n- In the locker room or on the bench before warm-ups\n- Right before free throws, as a one-second picture of the ball going in\n- After an injury or during a break, to stay connected to your skills\n- When learning a new move, to rehearse the steps between practices"},{"heading":"Pair it with real reps","body":"Visualization works best when it matches what you actually practice. If you picture a shot form you never use in the gym, it will not transfer.\n\nA good pattern is to practice a skill on the court, then picture it that night, then practice it again the next day. Start with a few minutes a few times a week. Consistency matters more than long sessions."}]'::jsonb, 4),
('sleep-for-athletes', 'recovery', 'Sleep for Athletes', 'Sleep is when your body recovers and your skills lock in. Learn how much you need, how to build a bedtime routine, and how to handle late games.', 6, '[{"heading":"Why sleep matters for your game","body":"Sleep is one of the most powerful recovery tools you have, and it is free. While you sleep, your body repairs muscles, releases growth hormone, and restores energy. Your brain also processes what you practiced, which helps new skills stick.\n\nWhen you do not get enough sleep, you may notice:\n- Slower reactions and worse decisions\n- Lower energy and motivation\n- Feeling more sore for longer\n- Worse mood and focus at school\n- Getting sick more often"},{"heading":"How much you need","body":"General guidance:\n- Teens (13 to 18) generally need 8 to 10 hours of sleep per night\n- Adults generally need at least 7 hours per night\n\nAthletes who train hard often feel best at the upper end of their range. A good sign you are getting enough is waking up without feeling groggy and having steady energy through the day."},{"heading":"Build a bedtime routine","body":"Your body likes a schedule. Try to:\n- Go to bed and wake up at similar times every day, including weekends\n- Start winding down 30 to 60 minutes before bed\n- Keep your room cool, dark, and quiet\n- Do something calm before bed, like reading, stretching, or your visualization routine\n- Get some daylight in the morning, which helps set your body clock\n\nExample wind-down: shower at 9:30, light stretching and pack your bag for tomorrow at 9:45, read at 10:00, lights out by 10:15."},{"heading":"Screens, caffeine, and late games","body":"Screens: Phones and games keep your brain alert. Try to put screens away 30 to 60 minutes before bed and keep your phone out of reach so you are not tempted to scroll.\n\nCaffeine: Coffee, soda, and energy drinks can keep you awake for hours. Energy drinks are not recommended for teens. Stick with water, and avoid caffeine in the afternoon and evening.\n\nLate games: After a night game, your body is still wired. Have a light snack and water, shower, and do a slow wind-down. You may fall asleep later than usual, so protect the next night''s sleep and keep the following morning easy if you can."},{"heading":"Naps and tough weeks","body":"Busy weeks with school, games, and travel happen. A few tips:\n- A short nap of about 20 to 30 minutes in the early afternoon can help you recharge\n- Avoid long or late-afternoon naps, which can make it harder to sleep at night\n- If you had a short night, prioritize an earlier bedtime the next night rather than a very long nap\n- During heavy weeks, cut screen time before you cut sleep"},{"heading":"When to get help","body":"Talk to a parent and a doctor if you regularly:\n- Have trouble falling or staying asleep for weeks at a time\n- Feel exhausted even after a full night of sleep\n- Snore loudly or are told you stop breathing during sleep\n- Fall asleep during class or at other unexpected times\n\nThis guide is general information, not medical advice."}]'::jsonb, 5),
('recovery-days-done-right', 'recovery', 'Recovery Days Done Right', 'Recovery days are when you actually get better. Learn active recovery, a 15-minute mobility routine, and when to take a lighter deload week.', 5, '[{"heading":"Why recovery days matter","body":"Training breaks your body down a little. Recovery is when it builds back stronger. If you train hard every day without a break, you stop improving and your injury risk goes up.\n\nMost players do well with at least 1 to 2 easier or full rest days per week. Many young athletes also benefit from taking some time away from basketball during the year to rest and try other activities."},{"heading":"Active recovery: what it looks like","body":"Active recovery means light movement that gets blood flowing without adding stress. It should feel easy, around 2 to 3 out of 10 effort. You should be able to hold a conversation the whole time.\n\nGood options, 20 to 40 minutes:\n- Easy walk or light bike ride\n- Easy swim or pool session\n- Light form shooting with no running\n- The mobility routine below\n\nWhat recovery is not: a hard pickup game, a sprint workout, or heavy lifting."},{"heading":"A 15-minute mobility routine","body":"Move slowly and breathe. Nothing should hurt.\n- Easy march or walk in place, 1 minute\n- Cat-cow on hands and knees, 8 to 10 slow reps\n- World''s greatest stretch (lunge, elbow to instep, then rotate open), 5 per side\n- Hip flexor stretch in a half-kneeling position, 30 to 45 seconds per side\n- 90-90 hip switches while seated, 8 to 10 reps\n- Hamstring stretch lying on your back with a towel, 30 to 45 seconds per side\n- Calf stretch against a wall, knee straight then knee bent, 30 seconds each per side\n- Ankle circles, 10 each direction per ankle\n- Thoracic rotations on your side (open book), 8 per side\n- Child''s pose with slow breathing, 1 minute\n\nIf you have a foam roller, you can add 30 to 60 seconds on calves, quads, and upper back."},{"heading":"Deload weeks","body":"A deload is a planned lighter week to let your body catch up. It is common to take one every 4 to 6 weeks of hard training, or after a heavy tournament stretch.\n\nDuring a deload:\n- Cut the total volume by about a third to a half (fewer sets, fewer jumps, shorter sessions)\n- Keep the same exercises, just lighter and fewer\n- Keep skill work sharp but short\n- Sleep and eat well\n\nYou might feel like you are doing too little. That is the point. Most players come out of a deload feeling fresher and jumping better."},{"heading":"Example recovery day","body":"- Morning: Wake at your normal time, drink water, eat a full breakfast\n- Afternoon: 20-minute easy walk or bike ride\n- After school: 15-minute mobility routine\n- Optional: 10 to 15 minutes of light form shooting close to the rim\n- Evening: Balanced dinner, screens off early, get to bed on time\n\nThe goal is to finish the day feeling better than when you started."}]'::jsonb, 6),
('managing-soreness-training-load', 'recovery', 'Managing Soreness and Training Load', 'Learn the difference between normal soreness and pain, how to use RPE to track effort, and the signs that it is time to back off.', 6, '[{"heading":"Normal soreness vs pain","body":"Normal muscle soreness usually shows up 1 to 2 days after a new or hard workout. It feels like a dull, achy tightness in the muscles you worked, and it gets better as you warm up and fades within a few days.\n\nPain that is a warning sign often:\n- Is sharp, stabbing, or in one specific spot\n- Is in a joint or bone rather than a muscle\n- Gets worse as you keep playing\n- Comes with swelling, bruising, or a joint that feels unstable\n- Changes the way you run, jump, or land\n\nSoreness means you worked. Pain means stop and get it checked."},{"heading":"Using RPE to rate effort","body":"RPE stands for Rating of Perceived Exertion. It is a simple 1 to 10 scale for how hard a session felt:\n- 1 to 2: Very easy, like walking\n- 3 to 4: Easy, you could keep going a long time\n- 5 to 6: Moderate, breathing harder but controlled\n- 7 to 8: Hard, you are pushing and talking is tough\n- 9: Very hard, close to your limit\n- 10: Maximum, you could not do any more\n\nRate each session about 15 to 30 minutes after you finish. Log it in the app so you can see your week at a glance."},{"heading":"Tracking your load","body":"A simple way to estimate how much stress a session puts on you is to multiply the RPE by the minutes. For example, a 60-minute practice at RPE 7 is 420 load points.\n\nAdd them up for the week and watch the trend:\n- Build up gradually from week to week instead of making big jumps\n- Avoid suddenly doubling your training, like adding extra camps and workouts all at once\n- Mix hard days with easy days. Two very hard days in a row should usually be followed by an easier one\n- Count everything: team practice, games, workouts, and pickup"},{"heading":"When to back off","body":"Take an easier day or a rest day if you notice:\n- Soreness that is not improving after 3 days\n- Heavy legs and a drop in your jump or speed for several days\n- Trouble sleeping or feeling tired all day\n- Low motivation or feeling irritable\n- A normal session feeling much harder than usual (your RPE is higher for the same work)\n\nBacking off for a day or two is much better than being forced off for weeks with an injury. Let your coach know how you are feeling so they can adjust."},{"heading":"When to get help","body":"This guide is general information, not medical advice.\n\nSee a doctor or physiotherapist if you have:\n- Pain, swelling, or bruising in a joint or bone\n- A joint that feels unstable or gives way\n- Pain that gets worse with activity or lasts more than a few days\n- Pain that makes you limp or wakes you at night\n- Very dark urine along with severe muscle pain or weakness after a hard workout, which needs medical care right away\n\nIf you are under 18, tell a parent, guardian, or coach so they can help."}]'::jsonb, 7),
('fueling-for-training-and-games', 'nutrition', 'Fueling for Training and Games', 'Build balanced meals, understand carbs and protein, and time your food around practice and games so you have energy from tip-off to the final buzzer.', 7, '[{"heading":"Food is your fuel","body":"Basketball uses a lot of energy: sprinting, jumping, cutting, and thinking fast for a whole game. Growing athletes also need energy to grow and recover. The goal is to eat enough, eat regularly, and eat a variety of real foods.\n\nKey habits:\n- Eat 3 meals a day plus snacks on training days\n- Do not skip breakfast\n- Eat enough to match your activity. If you are always tired or hungry, you probably need more\n- Focus on real food first. Growing athletes do not need supplements or diet products, and dieting or cutting food to lose weight can hurt your growth, energy, and performance"},{"heading":"Build a balanced plate","body":"A simple way to build a meal:\n- About a quarter to a third of the plate: carbs like rice, pasta, potatoes, bread, tortillas, or oats\n- About a quarter of the plate: protein like chicken, fish, eggs, beans, lentils, tofu, lean meat, or yogurt\n- About half the plate: vegetables and fruit, in lots of colors\n- A little healthy fat: olive oil, nuts, seeds, or avocado\n- A drink of water, and milk or a fortified alternative for calcium\n\nOn heavy training or game days, make the carb portion bigger. On rest days, the plate can have a bit less carbs and more vegetables."},{"heading":"Carbs and protein basics","body":"Carbs are your main fuel for high-intensity sports like basketball. They are stored in your muscles and liver and used during sprints and jumps. Running low on carbs can make you feel flat and slow late in games. Good sources include whole grains, fruit, potatoes, rice, pasta, and bread.\n\nProtein helps repair and build muscle after training. Spread it across the day instead of getting it all at dinner. Aim to include a protein source at every meal and in some snacks. Good sources include eggs, dairy, chicken, fish, beans, lentils, tofu, and nuts.\n\nFat and fruits and vegetables matter too, for overall health, vitamins, and minerals."},{"heading":"Timing: before, during, and after","body":"Before:\n- A full meal about 3 to 4 hours before training or a game, with carbs, some protein, and not too much fat or fiber\n- A small, easy snack 30 to 60 minutes before if you are hungry, like a banana, a granola bar, crackers, or a small sandwich\n\nDuring:\n- Water is usually enough for most practices\n- For long sessions or tournaments, a piece of fruit or a small snack between games can help\n\nAfter:\n- Eat a snack or meal with carbs and protein within about an hour or two after training\n- Good options: chocolate milk, yogurt with fruit, a turkey or peanut butter sandwich, or a normal dinner if it is soon after"},{"heading":"Example training day","body":"- Breakfast (7:00): Oatmeal with banana and peanut butter, a glass of milk, water\n- Snack (10:00): Apple and a handful of nuts\n- Lunch (12:30): Chicken or bean wrap with vegetables, a piece of fruit, yogurt, water\n- Pre-practice snack (3:30): Granola bar or crackers, water\n- Practice (4:30 to 6:30): Water throughout\n- Recovery snack (6:45): Chocolate milk or a sandwich\n- Dinner (7:30): Pasta or rice, salmon or lean meat or lentils, vegetables, water\n\nAdjust portions to your hunger. Bigger, more active players often need more."},{"heading":"When to get help","body":"Talk to a parent and a doctor or registered dietitian if you:\n- Feel tired, dizzy, or weak often\n- Are losing weight without trying\n- Feel worried or stressed about food, your weight, or your body\n- Have food allergies or a special diet and are unsure how to fuel for sport\n\nThis guide is general information, not medical or nutrition advice for your specific needs."}]'::jsonb, 8),
('hydration-for-basketball', 'nutrition', 'Hydration for Basketball', 'Stay sharp on the court with simple daily hydration habits, a before-during-after plan, and why water beats energy drinks for young athletes.', 5, '[{"heading":"Why hydration matters","body":"You lose water through sweat every time you play, and even more in hot gyms or outdoor courts. When you start to get dehydrated, you may notice:\n- Feeling tired or sluggish earlier than normal\n- Headaches or dizziness\n- Worse focus and slower decisions\n- Muscle cramps\n\nStaying hydrated helps you keep your energy, focus, and legs through the whole game."},{"heading":"Daily habits","body":"Hydration starts long before tip-off:\n- Carry a reusable water bottle and sip through the day\n- Drink water with every meal and snack\n- Check your urine color. Pale yellow usually means you are well hydrated. Dark yellow means drink more\n- Drink more on hot days, during tournaments, and when you are sick\n- Fruits, vegetables, milk, and soups also count toward your fluids"},{"heading":"Before, during, and after","body":"Before:\n- Drink water with your pre-game meal\n- Have a glass or two of water in the couple of hours before you play\n- Top up with a few sips right before warm-ups\n\nDuring:\n- Drink at every timeout and break, even if you do not feel thirsty yet\n- Small, regular sips are better than chugging a lot at once\n\nAfter:\n- Keep drinking water after you finish\n- Eat a meal or snack, since food helps replace the salt you lost in sweat\n- Check your urine color later that evening. If it is still dark, keep sipping water"},{"heading":"Water vs sports drinks vs energy drinks","body":"Water is the best choice for most practices and games.\n\nSports drinks can be helpful for long, intense sessions (over about an hour), tournaments with several games in a day, or very hot and sweaty conditions. For normal practice, water plus your regular meals is usually enough.\n\nEnergy drinks are not the same as sports drinks. They often contain high amounts of caffeine and other stimulants, which can cause a racing heart, jitters, trouble sleeping, and upset stomach. Energy drinks are not recommended for kids and teens. Choose water instead."},{"heading":"Heat and warning signs","body":"Hot gyms and outdoor summer courts raise the risk of heat illness. Take extra breaks, drink more, and use shade when you can.\n\nStop playing, tell a coach or adult, and cool down right away if you feel:\n- Dizzy, faint, or confused\n- Nauseous or you vomit\n- A bad headache\n- Very hot with chills or goosebumps, or you stop sweating\n- Muscle cramps that will not go away\n\nIf someone is confused, collapses, or cannot drink, call emergency services. This guide is general information, not medical advice."}]'::jsonb, 9),
('ankle-sprain-prevention', 'injury_prevention', 'Ankle Sprain Prevention', 'Ankle sprains are among the most common basketball injuries. Build balance, ankle strength, and landing habits that help keep you on the court.', 6, '[{"heading":"Why ankles get hurt in basketball","body":"Ankle sprains are one of the most common injuries in basketball. They often happen when you land on someone else''s foot, change direction quickly, or land off-balance after a rebound or shot. The ankle rolls, usually outward, and the ligaments on the outside get stretched or torn.\n\nA past sprain is one of the biggest risk factors for another one, especially if it was not fully rehabbed. The good news is that balance and strength training can help lower your risk."},{"heading":"Balance training","body":"Balance work trains the nerves and muscles around your ankle to react faster. Do these 3 times a week, barefoot or in shoes:\n- Single-leg stand: 30 seconds per leg, 3 rounds. Progress by closing your eyes\n- Single-leg stand with ball catches: have a partner toss you a ball, or toss it against a wall, 20 catches per leg\n- Single-leg reaches: stand on one leg and reach the other foot forward, to the side, and behind, 5 each direction per leg\n- Single-leg stand on a pillow or folded towel for more challenge, 30 seconds per leg\n\nKeep a soft knee and stay tall. A little wobble is normal and means your ankle is working."},{"heading":"Strength for calves and ankles","body":"Strong calves and ankle muscles help control your landings:\n- Double-leg calf raises: 2 to 3 sets of 15, slow up and slow down\n- Single-leg calf raises: 2 to 3 sets of 10 to 12 per leg, holding a wall for balance\n- Bent-knee calf raises: 2 sets of 12 to 15, to hit the deeper calf muscle\n- Band ankle movements (if you have a resistance band): push out, pull in, point, and flex, 2 sets of 15 each direction\n- Heel walks and toe walks: 20 steps each\n\nAdd these to the end of a workout 2 to 3 times a week."},{"heading":"Landing, footwear, and awareness","body":"- Land on both feet when you can, with soft knees and your weight over the middle of your feet\n- Practice sticking landings from small jumps before you add height and speed\n- Wear basketball shoes that fit well, are laced up snugly, and are not worn out\n- Replace shoes when the grip or cushioning is clearly worn\n- Be aware in the paint. Many sprains happen when landing near other players\n- Always do a proper warm-up before you play"},{"heading":"If you have sprained your ankle before","body":"Finish your rehab even after the pain is gone. Many repeat sprains happen because players go back before their balance and strength are fully back.\n\nBefore returning to full play, you should generally be able to:\n- Walk, jog, and sprint without limping\n- Hop on the injured leg without pain\n- Balance on the injured leg about as well as the other one\n- Cut and change direction with confidence\n\nAn ankle brace or taping may help some players, especially after a recent sprain. Ask a physiotherapist or athletic trainer what is right for you."},{"heading":"When to get help","body":"This guide is general information, not medical advice.\n\nSee a doctor or physiotherapist if you notice:\n- Pain that is sharp, gets worse, or lasts more than a few days\n- Swelling, bruising, or a joint that looks different from the other side\n- A joint that feels unstable, gives way, locks, or catches\n- Pain that makes you limp or changes how you move\n- Numbness, tingling, or pain that wakes you up at night\n\nIf you are under 18, tell a parent, guardian, or coach so they can help you get checked. Getting assessed early usually means a faster, safer return to the court.\n\nFor ankles specifically, get checked right away if you cannot put weight on your foot, if there is pain directly on the bone, or if the ankle looks deformed."}]'::jsonb, 10),
('knee-health-jumping-landing', 'injury_prevention', 'Knee Health: Jumping and Landing Mechanics', 'Learn how to land softly and safely, with clear cues, a landing drill progression, and strength work that helps protect your knees.', 7, '[{"heading":"Why landing mechanics matter","body":"Basketball players jump and land hundreds of times per week. How you land matters. Landing stiff-legged or letting your knees cave inward puts extra stress on the ligaments in your knee.\n\nThe good news is that landing technique is a skill you can learn. Injury prevention programs that include landing practice, balance work, and strength training are widely recommended for young athletes, especially in jumping and cutting sports."},{"heading":"The good landing checklist","body":"Use these cues every time you land:\n- Land softly and quietly, like a ninja. Loud landings usually mean stiff landings\n- Land on the balls of your feet, then let your heels come down\n- Bend your hips and knees to absorb the landing, like sitting back into a chair\n- Keep your knees in line over your toes. Do not let them cave in toward each other\n- Feet about hip-width to shoulder-width apart\n- Chest up, with your chest over your knees\n- Land on two feet when you can\n\nFilm yourself from the front doing a few jumps. Look for knees staying over toes."},{"heading":"Landing drill progression","body":"Work through these in order. Move up a level when you can do 3 sets with good form every rep.\n- Level 1: Squat to a stick. Do slow bodyweight squats and freeze at the bottom for 2 seconds, 3 sets of 8\n- Level 2: Snap-downs. From standing on your toes, drop quickly into a landing position and stick it, 3 sets of 5\n- Level 3: Jump and stick. Small jump in place, land and freeze for 2 seconds, 3 sets of 5\n- Level 4: Forward hop and stick. Hop forward about a step, land and freeze, 3 sets of 5\n- Level 5: Lateral hop and stick. Hop sideways and stick on two feet, then progress to one foot, 3 sets of 5 per side\n- Level 6: Single-leg hop and stick, 3 sets of 5 per leg\n\nQuality over quantity. Stop the set if your knees start to cave."},{"heading":"Strength that protects your knees","body":"Strong hips and legs help control your knees. Do these 2 to 3 times a week:\n- Bodyweight squats or goblet squats: 3 sets of 8 to 12\n- Reverse lunges: 3 sets of 8 per leg\n- Glute bridges: 3 sets of 12, progress to single-leg bridges\n- Side-lying leg raises or banded side steps: 2 to 3 sets of 12 to 15 per side\n- Hamstring work like single-leg Romanian deadlifts or hamstring walkouts: 2 to 3 sets of 8\n- Step-downs from a low step, slowly, keeping the knee over the toes: 2 sets of 8 per leg\n\nIf you are new to lifting weights, learn technique with bodyweight first and get coaching from a qualified adult before adding load."},{"heading":"Listen to your knees","body":"Growing athletes sometimes feel achy pain around the front of the knee or just below the kneecap, especially during growth spurts and busy seasons. This is common in jumping sports, but it should not be ignored.\n\nHelpful steps:\n- Track your jumping volume and avoid sudden big increases\n- Build in rest days\n- Keep up your strength and mobility work\n- Tell your coach and a parent if your knees hurt during or after play"},{"heading":"When to get help","body":"This guide is general information, not medical advice.\n\nSee a doctor or physiotherapist if you notice:\n- Pain that is sharp, gets worse, or lasts more than a few days\n- Swelling, bruising, or a joint that looks different from the other side\n- A joint that feels unstable, gives way, locks, or catches\n- Pain that makes you limp or changes how you move\n- Numbness, tingling, or pain that wakes you up at night\n\nIf you are under 18, tell a parent, guardian, or coach so they can help you get checked. Getting assessed early usually means a faster, safer return to the court.\n\nFor knees specifically, get checked right away if you felt or heard a pop, if the knee swells quickly, or if it gives way when you cut or land."}]'::jsonb, 11),
('warm-up-that-actually-works', 'injury_prevention', 'Warm-Up That Actually Works', 'A 12-minute dynamic warm-up that raises your temperature, wakes up your muscles, and gets you game-ready. Skip the lazy stretch-and-shoot.', 5, '[{"heading":"Why a real warm-up matters","body":"A few layups and a quick stretch is not a warm-up. A good warm-up raises your body temperature, gets your joints moving, turns on the muscles you need for jumping and cutting, and gets your nervous system ready to move fast.\n\nWarm-up programs that include movement, balance, and landing practice are widely recommended to help reduce injury risk in youth sports. They also help you play better from the first possession.\n\nSave long, still stretches (holding a stretch for 30 seconds or more) mostly for after practice or recovery days. Before you play, keep things moving."},{"heading":"The structure","body":"A simple way to remember a good warm-up:\n- Raise: get your heart rate and body temperature up\n- Mobilize: move your joints through their full range\n- Activate: wake up your hips, glutes, and core\n- Prime: practice fast, sharp movements you will use in the game\n\nEach phase builds on the one before it, from easy to game speed."},{"heading":"The 12-minute routine","body":"Use about half the court length for movements that travel.\n\nRaise (2 minutes):\n- Light jog down and back\n- Side shuffles down and back\n- Backpedal down and back\n\nMobilize (3 minutes):\n- Walking knee hugs, 10 steps\n- Walking quad pulls, 10 steps\n- Walking lunges with a twist, 8 per leg\n- Leg swings front to back and side to side, 10 each per leg\n- Inchworms, 5 reps\n\nActivate (3 minutes):\n- Glute bridges, 10 reps\n- Mini-band lateral walks or side steps, 10 steps each way\n- Bodyweight squats, 10 reps\n- Single-leg balance, 20 seconds per leg\n\nPrime (4 minutes):\n- A-skips down and back\n- Carioca down and back\n- Pogo hops in place, 2 sets of 10\n- Jump and stick landings, 5 reps\n- Defensive slides with a quick closeout, 2 trips\n- Two build-up sprints to about 70 then 90 percent effort\n\nThen move into your ball-handling and shooting warm-up."},{"heading":"Adjusting for games vs practice","body":"- Game days: Do the full routine, finishing about 5 to 10 minutes before tip-off so you stay warm without getting tired\n- Practice days: The full routine, or a shorter version if your team does its own warm-up\n- Cold gyms or early mornings: Add an extra couple of minutes to the Raise phase\n- Coming off the bench: Stay warm with light movement, like calf raises, leg swings, and a few quick shuffles, a few minutes before you check in\n- Second half: Do a short 2 to 3 minute re-warm-up with jogging, skips, and a few hops"},{"heading":"When to get help","body":"A warm-up should make you feel looser and more ready. It should not cause pain.\n\nThis guide is general information, not medical advice. If you notice pain, swelling, or a joint that feels unstable during or after your warm-up, stop and see a doctor or physiotherapist. If you are under 18, tell a parent, guardian, or coach so they can help you get checked."}]'::jsonb, 12),
('how-to-jump-higher', 'vertical', 'How to Jump Higher: The Science and a Plan', 'What actually makes you jump higher, how strength, plyometrics, and technique fit together, and how to follow the 8-Week Vertical Jump Program.', 7, '[{"heading":"What makes a jump high","body":"Your vertical depends on how much force you can push into the ground and how fast you can do it. Three things drive that:\n- Strength: how much force your legs and hips can produce\n- Speed and elasticity: how quickly you can load and explode, using your muscles and tendons like a spring\n- Technique: your approach, arm swing, and body position\n\nGenetics and growth play a part too, but almost every player can improve by training all three. Improvement takes weeks and months, not days."},{"heading":"Build the base: strength","body":"Stronger legs and hips give you more force to put into the ground. Key exercises:\n- Squats (bodyweight, goblet, or with more load as you progress)\n- Split squats and reverse lunges\n- Hip hinges like Romanian deadlifts or glute bridges\n- Calf raises, both double and single-leg\n- Core work like planks and side planks\n\nFor teens, strength training is safe and effective when it is supervised, uses good technique, and progresses gradually. Master bodyweight versions first, then add load with help from a qualified coach."},{"heading":"Plyometrics: training the spring","body":"Plyometrics are jumping and hopping drills that train your muscles and tendons to store and release energy quickly. Start simple and build up:\n- Pogo hops: quick, small bounces on the balls of your feet\n- Box jumps: jump up onto a stable box and step down, focusing on the jump, not the height of the box\n- Broad jumps: jump forward as far as you can and stick the landing\n- Lateral bounds: jump side to side and stick each landing\n- Later: continuous jumps and approach jumps\n\nKey rules:\n- Quality over quantity. Stop sets when your jumps get slower or sloppier\n- Rest fully between sets, about 60 to 90 seconds\n- Land using the cues from the Knee Health guide\n- Count your jumps and do not suddenly add a lot more"},{"heading":"Technique: free inches","body":"Small technique fixes can add height right away:\n- Arm swing: swing your arms back as you load, then drive them up hard as you jump\n- Approach: on a running jump, use 2 to 3 controlled steps, with a longer, lower penultimate step before takeoff\n- Load: dip to a comfortable depth, not too shallow and not too deep, and explode up\n- Full extension: push through your hips, knees, and ankles all the way at takeoff\n\nFilm a few jumps from the side to check your arm swing and depth."},{"heading":"Your plan: the 8-Week Vertical Jump Program","body":"The app''s 8-Week Vertical Jump Program puts all of this into a structured plan, so you do not have to guess what to do each day. It builds from a foundation of strength, landing mechanics, and basic plyometrics toward more explosive jumping as the weeks go on.\n\nTo get the most from it:\n- Test your vertical at the start so you have a baseline\n- Follow the sessions in order and do not skip ahead\n- Log each workout and your RPE in the app\n- Retest your vertical every 2 weeks, fresh and well warmed up, at the same time of day\n- Keep a warm-up before every session\n\nFind it under Programs in the app and start with Week 1."},{"heading":"Recovery, patience, and safety","body":"Jump training is demanding on your legs and tendons. You get better during recovery, not just during the workout.\n- Leave at least a day between hard jumping or lifting sessions for the same muscles\n- Count your basketball practices and games as jump volume too. On heavy game weeks, lighter program sessions may be smarter\n- Sleep 8 to 10 hours if you are a teen, and eat enough to support your training\n- Stop and rest if you feel sharp pain in your knees, ankles, shins, or feet\n\nThis guide is general information, not medical advice. If you have pain, swelling, or a joint that feels unstable, see a doctor or physiotherapist before continuing."}]'::jsonb, 13),
('game-day-routine', 'game_prep', 'Game-Day Routine: Night Before to Final Buzzer', 'A step-by-step game-day plan covering sleep, meals, warm-up, focus during the game, and recovery after, so you show up ready every time.', 6, '[{"heading":"The night before","body":"Good games start the night before:\n- Eat a normal, balanced dinner with a solid portion of carbs, like rice, pasta, or potatoes, plus protein and vegetables\n- Drink water through the evening\n- Pack your bag: shoes, socks, uniform, water bottle, snacks, any brace or tape you use, and a warm layer\n- Do a 5-minute visualization of your role in the game\n- Screens off 30 to 60 minutes before bed and aim for your normal bedtime\n\nNerves are normal. If you cannot fall asleep right away, that is fine. Rest, breathe slowly, and do not stress about it."},{"heading":"Game-day morning and meals","body":"Keep your routine familiar. Game day is not the time to try new foods.\n- Wake at your usual time and drink a glass of water\n- Eat a full breakfast, like eggs with toast and fruit, or oatmeal with banana and yogurt\n- Eat your main pre-game meal about 3 to 4 hours before tip-off: carbs, lean protein, and not too heavy or greasy. For example, a chicken and rice bowl, pasta with a lean sauce, or a turkey sandwich with fruit\n- If you are hungry 30 to 60 minutes before, have a light snack like a banana or crackers\n- Sip water steadily through the day and skip energy drinks\n- Stay off your feet a bit. Light activity is fine, but save your legs"},{"heading":"Before tip-off","body":"- Arrive early enough that you never feel rushed\n- Put on music or find a quiet spot to get in your zone, whatever works for you\n- Do the full dynamic warm-up from the Warm-Up guide\n- Get your touches: form shots close to the rim, then spot-ups from your usual spots, then a few free throws with your full routine\n- Set 1 to 3 simple goals you control, like \"sprint back every possession,\" \"talk on defense,\" \"use my free-throw routine\"\n- Take a few slow breaths before the tip. In through the nose, long breath out"},{"heading":"During the game","body":"- Play one possession at a time. The last play is done\n- Use your next-play reset after any mistake\n- Drink water at every timeout and between quarters\n- Stay warm on the bench with light movement if you are not playing\n- At halftime, have a few sips of water, listen to your coach, and do a short re-warm-up before the second half\n- Focus on effort, energy, and communication. They are always in your control"},{"heading":"After the final buzzer","body":"Your next performance starts right after this one ends.\n- Cool down with 5 minutes of easy walking and light stretching\n- Drink water and have a snack with carbs and protein within about an hour, like chocolate milk, yogurt, or a sandwich, then a full meal\n- Take a few minutes to reflect: 2 or 3 things you did well and 1 thing to work on. Log the game in the app\n- Then let it go, win or lose\n- Get to bed as close to your normal time as you can\n- Make the next day an easy or recovery day if possible"}]'::jsonb, 14)
ON CONFLICT (slug) DO NOTHING;
